mapper.select:
SELECT * FROM consultation_message WHERE consultation_id=#{id}
AND id>#{after}
AND id<#{before}
ORDER BY id ASCDESC LIMIT #{limit}

mapper.sql:
FROM consultation_doctor d JOIN user_account u ON u.id=d.user_id
WHERE u.is_deleted=0 AND u.account_status=1
AND d.status=#{status}

mapper.update:
UPDATE consultation_doctor SET status=#{form.status},review_note=#{form.reviewNote},reviewed_by=#{ops},
    reviewed_at=CURRENT_TIMESTAMP(3),version=version+1
WHERE user_id=#{user} AND version=#{form.version}

mapper.sql:
FROM consultation_request c JOIN user_account u ON u.id=c.patient_id
LEFT JOIN user_profile p ON p.user_id=u.id AND p.is_deleted=0
LEFT JOIN consultation_topic ct ON ct.code=c.topic
WHERE u.is_deleted=0 AND u.account_status=1
AND c.patient_id=#{viewer}
AND c.doctor_user_id=#{viewer}
AND c.patient_id<>#{viewer}
AND c.status='WAITING' AND c.doctor_user_id IS NULL
AND c.topic=#{topic}
